{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "The closest analogue, tirabrutinib, achieved measurable unbound brain exposure (Kp,uu 8.5% at Cmax) in rats and was classified as permeable, directly supporting meaningful CNS access for the closely related query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "PET imaging in monkeys showed high brain uptake for a structurally related compound, demonstrating that this chemotype crosses the BBB in vivo.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A close analogue with a similar fused aromatic/piperidine scaffold achieved a brain:blood ratio of 6.8 in rats, indicating high brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In humans, a related compound had CSF concentrations at least equal to free plasma concentrations, providing translational evidence for meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Another close analogue showed good CNS penetration in rats with a brain/plasma ratio of 1.66, reinforcing the pattern of adequate brain access for this structural family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close analogue of tirabrutinib and other CNS-penetrant kinase inhibitors; direct in vivo, PET, and human CSF evidence from high-transfer analogues consistently demonstrates meaningful brain access, so the prediction is pass.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query molecule.",
    "The closest direct analogue has a modest unbound brain-to-plasma ratio (8.5%), and transporter-mediated efflux was not explicitly ruled out.",
    "The acrylamide warhead could alter disposition relative to the alkyne analogue, though this is unlikely to negate the overall CNS-penetrant phenotype."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

